import{_ as s,c as a,o as t,ag as i}from"./chunks/framework.C86mscM5.js";const c=JSON.parse('{"title":"Nexus Repository","description":"","frontmatter":{},"headers":[],"relativePath":"devops/registries/nexus.md","filePath":"devops/registries/nexus.md","lastUpdated":1788689791000}'),o={name:"devops/registries/nexus.md"};function r(n,e,p,l,d,u){return t(),a("div",null,e[0]||(e[0]=[i('<h1 id="nexus-repository" tabindex="-1">Nexus Repository <a class="header-anchor" href="#nexus-repository" aria-label="Permalink to &quot;Nexus Repository&quot;">​</a></h1><p>Nexus Repository 是常见的制品仓库管理器，可以代理公共软件源并托管组织内部制品。它适合为 npm、Maven、PyPI、NuGet 和通用文件提供统一的下载与发布入口。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><ul><li><strong>proxy</strong>：代理外部软件源并缓存已经下载的制品。</li><li><strong>hosted</strong>：保存组织内部发布的私有制品。</li><li><strong>group</strong>：将多个 proxy 和 hosted 仓库聚合为一个访问地址。</li></ul><p>典型做法是让开发环境和 CI 只访问 group 仓库。Nexus 根据配置先查找内部制品和缓存，必要时再请求外部源。</p><h2 id="npm-使用方式" tabindex="-1">npm 使用方式 <a class="header-anchor" href="#npm-使用方式" aria-label="Permalink to &quot;npm 使用方式&quot;">​</a></h2><p>将项目的下载地址指向 npm group 仓库：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">registry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://nexus.example.com/repository/npm-group/</span></span></code></pre></div><p>发布私有包时使用单独的 hosted 仓库，并通过项目级 <code>.npmrc</code> 或流水线密钥提供身份凭据。不要把访问令牌提交到代码仓库。</p><h2 id="生产建议" tabindex="-1">生产建议 <a class="header-anchor" href="#生产建议" aria-label="Permalink to &quot;生产建议&quot;">​</a></h2><ul><li>将下载权限和发布权限分离，发布权限只授予流水线及少数维护者。</li><li>公共代理、私有发布和快照制品使用不同仓库，分别设置清理策略。</li><li>禁止覆盖正式版本；修复后发布新版本，而不是替换已经使用的制品。</li><li>备份 blob 数据、数据库和配置，并定期执行恢复演练。</li><li>对外部依赖设置允许列表、漏洞检查或隔离流程，避免未经验证的依赖直接进入生产构建。</li></ul><p>如果只需要简单的 npm 私有仓库，可以先评估更轻量的方案；需要同时管理多种包格式、统一权限和缓存时，Nexus 更有价值。</p>',12)]))}const m=s(o,[["render",r]]);export{c as __pageData,m as default};
